/**
 * The provenance of an import in PROV-O (commons 0019-mizan-integrations FR-009): the generated module is a `prov:Entity` generated by an import, a `prov:Activity` that used the
 * pinned source, itself an entity named by its SHA-256, so that what a module rests on can be read by any PROV tool.
 *
 * @remarks
 * It is Turtle, written deterministically from the record: no date, no host, so the same import gives the same text.
 *
 * @example
 * ```ts
 * import { provenanceTurtle } from "./provenance.ts";
 * // provenanceTurtle(record, "schema.auto.ts") // @prefix prov: ... <urn:ifc:mizan:module:schema-org> a prov:Entity ...
 * ```
 *
 * @module
 */
import type { ImportRecordData } from "./import-vocabulary.ts";

function lit(s: string): string {
  return `"${s.replaceAll("\\", "\\\\").replaceAll('"', '\\"').replaceAll("\n", "\\n")}"`;
}

/** The record as PROV-O Turtle: the module, the import that made it, the source it used and where the source is from. */
export function provenanceTurtle(r: ImportRecordData, moduleFile: string): string {
  const source = `<urn:sha256:${r.sha256}>`;
  const activity = `<urn:ifc:mizan:import:${r.standard}:${r.sha256}>`;
  const module = `<urn:ifc:mizan:module:${r.standard}>`;
  const license = r.license.startsWith("LicenseRef-") ? lit(r.license) : `<https://spdx.org/licenses/${r.license}.html>`;
  return [
    `# AUTO-GENERATED with ${moduleFile} by ${r.generator} (commons 0019-mizan-integrations FR-009). Do not edit.`,
    ``,
    `@prefix dcterms: <http://purl.org/dc/terms/> .`,
    `@prefix prov: <http://www.w3.org/ns/prov#> .`,
    ``,
    `${module} a prov:Entity ;`,
    `    dcterms:source ${lit(moduleFile)} ;`,
    `    prov:wasGeneratedBy ${activity} ;`,
    `    prov:wasDerivedFrom ${source} .`,
    ``,
    `${activity} a prov:Activity ;`,
    `    prov:used ${source} ;`,
    `    prov:wasAssociatedWith <urn:ifc:mizan:generator:${r.generator.replaceAll("/", ":")}> .`,
    ``,
    `<urn:ifc:mizan:generator:${r.generator.replaceAll("/", ":")}> a prov:SoftwareAgent .`,
    ``,
    `${source} a prov:Entity ;`,
    `    dcterms:title ${lit(r.name)} ;`,
    `    dcterms:publisher ${lit(r.issuer)} ;`,
    `    dcterms:hasVersion ${lit(r.version)} ;`,
    `    dcterms:source <${r.location}> ;`,
    `    dcterms:license ${license} .`,
    ``,
  ].join("\n");
}
